SET SERVEROUTPUT ON
BEGIN
  FOR r IN (SELECT immat, marque, modele, prixjour FROM voiture ORDER BY immat) LOOP
    DBMS_OUTPUT.PUT_LINE(r.immat || ' : ' || r.marque || ' ' || r.modele || ' - ' ||
      CASE WHEN r.prixjour < 20000 THEN 'Economique' ELSE 'Premium' END);
  END LOOP;
END;
/
- Boucle FOR sur une requête : pas de curseur à déclarer, pas de variable r à déclarer.

CREATE OR REPLACE PROCEDURE louervoiture (
  p_idclient IN NUMBER, p_immat IN VARCHAR2,
  p_datedebut IN DATE, p_datefin IN DATE, p_idloc OUT NUMBER
) IS
  v_nb   NUMBER;
  v_prix voiture.prixjour%TYPE;
BEGIN
  SELECT COUNT(*) INTO v_nb FROM location
  WHERE immat = p_immat AND datedebut <= p_datefin AND datefin >= p_datedebut;
  IF v_nb > 0 THEN
    RAISE_APPLICATION_ERROR(-20401, 'Voiture indisponible sur cette periode');
  END IF;

  SELECT prixjour INTO v_prix FROM voiture WHERE immat = p_immat;
  p_idloc := seq_loc.NEXTVAL;
  INSERT INTO location (idloc, idclient, immat, datedebut, datefin, montant)
  VALUES (p_idloc, p_idclient, p_immat, p_datedebut, p_datefin, (p_datefin - p_datedebut) * v_prix);
END louervoiture;
/
- Chevauchement : début existant avant ma fin ET fin existante après mon début.
- Une voiture inexistante lèvera NO_DATA_FOUND (à traiter par une erreur applicative si demandé).

CREATE OR REPLACE TRIGGER trg_location_dates
BEFORE INSERT OR UPDATE OF datedebut, datefin ON location
FOR EACH ROW
BEGIN
  IF :NEW.datefin < :NEW.datedebut THEN
    RAISE_APPLICATION_ERROR(-20402, 'La date de fin precede la date de debut');
  END IF;
END;
/
- UPDATE OF avec deux colonnes : déclenché si l'une des deux figure dans le SET.

CREATE OR REPLACE FUNCTION caagence (p_code IN NUMBER) RETURN NUMBER IS
  v_ca NUMBER;
BEGIN
  SELECT NVL(SUM(l.montant), 0) INTO v_ca
  FROM location l JOIN voiture v ON v.immat = l.immat
  WHERE v.codeagence = p_code;
  RETURN v_ca;
END;
/
